        return []
    df = pd.read_csv(io.StringIO(text), thousands=',')
    sales = []
    for record in df.to_dict('records'):
        sales.append(
            {
                'product': str(record['product']),
                'quantity': int(record['quantity']),
                'price': float(record['price']),
            }
        )
    return sales


