import io
import json
import pandas as pd


def _to_plain(value):
    if isinstance(value, bool):
        return bool(value)
    if hasattr(value, "item"):
        value = value.item()
    if isinstance(value, bool):
        return value
    if isinstance(value, int):
        return int(value)
    if isinstance(value, float):
        return float(value)
    return value


def read_sales(text):
    if not text or not text.strip():
        return []
    df = pd.read_csv(io.StringIO(text), dtype={"price": str})
    sales = []
    for record in df.to_dict("records"):
        product = str(record["product"])
        quantity = record["quantity"]
        if isinstance(quantity, str):
            quantity = quantity.replace(",", "")
        quantity = int(quantity)
        price = record["price"]
        if isinstance(price, str):
            price = price.replace(",", "").strip()
        price = float(price)
        sales.append({"product": product, "quantity": quantity, "price": price})
    return sales


def totals(sales):
    result = {}
    for row in sales:
        product = row["product"]
        amount = float(row["quantity"]) * float(row["price"])
        result[product] = result.get(product, 0.0) + amount
    return {product: float(amount) for product, amount in result.items()}


def save_report(path, sales):
    by_product = totals(sales)
    if sales:
        total = float(sum(float(row["quantity"]) * float(row["price"]) for row in sales))
        best = max(by_product, key=lambda product: by_product[product])
    else:
        total = 0
        best = None

    report = {
        "total": _to_plain(total),
        "by_product": {_to_plain(product): _to_plain(amount) for product, amount in by_product.items()},
        "best": _to_plain(best),
    }
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(report, handle)


def load_report(path):
    with open(path, "r", encoding="utf-8") as handle:
        return json.load(handle)
